gadT(){return"\u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629"},
gadQ(){return"\u0627\u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629"},
gadP(){return"\u0625\u0636\u0627\u0641\u0629 \u0646\u0648\u0639"},
gadU(){return"\u0623\u062f\u062e\u0644 \u0627\u0633\u0645\u064b\u0627 \u0648\u0627\u062e\u062a\u0631 \u0646\u0648\u0639\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644."},
adI(a,b){var s=null,r=this.a
return A.cI(a,s,r,s,"\u0645\u0627\u062f\u0629 \u0648\u0627\u062d\u062f\u0629",""+a+" \u0645\u0627\u062f\u0629",s,s)+" \xb7 "+A.cI(b,s,r,s,"\u0645\u0631\u062d\u0644\u0629 \u0648\u0627\u062d\u062f\u0629",""+b+" \u0645\u0631\u062d\u0644\u0629",s,s)+" \u0641\u064a \u062e\u0637 \u0627\u0644\u0625\u0646\u062a\u0627\u062c"},
